package nl.juiced.guhs.feature.vadsrijk.bazen;

import java.util.List;

import net.minecraft.core.BlockPos;
import nl.juiced.guhs.feature.vadsrijk.wereld.WereldPlekken;

/**
 * Every coordinate the bazen slice uses (SLICE_BRIEF: one class). Integration 1.10.0: aligned with the real map
 * ({@link WereldPlekken} / POI_VADSRIJK.md v1, generated by tools/vadsrijk/maak_kaart.py): the Koning Klodder arena on the
 * Klodderweide (ground y 69), the Zwamtempel on the mountain (floor block y 151, stand y 152; the chain voorhal -> gate z -405 ->
 * Lichtzwamkamer -> gate z -426 -> Hendelkamer -> gate z -447 -> Ridderzaal -> gate z -472..-476 -> the Opperzwam hall), the
 * temple door = wereld's moving door "zwamtempel", the Mika-spion's stall and caps in Zwamzoet (ground y 64).
 */
public final class BazenPlekken {
    private BazenPlekken() {
    }

    private static BlockPos w(String id) {
        return WereldPlekken.plek(id);
    }

    // ---- Koning Klodder: the arena on the Klodderweide -----------------------------------------------------------------------
    public static final BlockPos KK_CENTRUM = w("arena_koning_klodder.centrum");
    public static final int KK_STRAAL = 32;
    public static final BlockPos KK_DEUR = w("arena_koning_klodder.deur");
    public static final BlockPos KK_BORD = w("arena_koning_klodder.bord");
    public static final int KK_RESPAWN = 20 * 60;

    // ---- De Zwamtempel ------------------------------------------------------------------------------------------------------
    public static final int TEMPEL_VLOER = 152;   // the first air block above the temple floor
    /** The big temple door (wereld's moving door "zwamtempel"): x 324..336, y 152..175, z -392. */
    public static final BlockPos TEMPELDEUR_MIN = w("deur_zwamtempel.min"), TEMPELDEUR_MAX = w("deur_zwamtempel.max");
    public static final BlockPos TEMPELDEUR_VOOR = w("deur_zwamtempel.voor");
    public static final int TEMPEL_MIN_LEVEL = 16;

    /** The gates wereld leaves as open air (x 328..332, y 152..155; the last x 327..333, y 152..156, z -476..-472). */
    private static BlockPos poort(int i) {
        return w("poorten." + i);
    }

    /** Room 1, the Lichtzwamkamer (inside x 318..342, z -425..-406). Its exit = gate 2. */
    public static final BlockPos K1_MIN = new BlockPos(318, TEMPEL_VLOER - 1, -425), K1_MAX = new BlockPos(342, TEMPEL_VLOER + 9, -406);
    public static final List<BlockPos> K1_ZWAMMEN = List.of(w("lichtzwamkamer.lichtzwammen.1"), w("lichtzwamkamer.lichtzwammen.2"),
            w("lichtzwamkamer.lichtzwammen.3"), w("lichtzwamkamer.lichtzwammen.4"), w("lichtzwamkamer.lichtzwammen.5"));
    public static final BlockPos K1_POORT_MIN = poort(2), K1_POORT_MAX = poort(2).offset(4, 3, 0);

    /** Room 2, the Hendelkamer (inside x 318..342, z -446..-427). Its exit = gate 3. */
    public static final BlockPos K2_MIN = new BlockPos(318, TEMPEL_VLOER - 1, -446), K2_MAX = new BlockPos(342, TEMPEL_VLOER + 9, -427);
    public static final List<BlockPos> K2_HENDELS = List.of(w("hendelkamer.hendels.1"), w("hendelkamer.hendels.2"), w("hendelkamer.hendels.3"),
            w("hendelkamer.hendels.4"));
    /** The hint mushrooms on the north wall, seen from the levers they are mirrored (index i hints lever i). */
    public static final List<BlockPos> K2_HINTS = List.of(w("hendelkamer.hints.1"), w("hendelkamer.hints.2"), w("hendelkamer.hints.3"),
            w("hendelkamer.hints.4"));
    public static final BlockPos K2_PLAAT = w("hendelkamer.plaat");
    public static final BlockPos K2_POORT_MIN = poort(3), K2_POORT_MAX = poort(3).offset(4, 3, 0);

    /** Room 3, the Ridderzaal (inside x 314..346, z -472..-448). Its entrance is K2's gate; its exit gate (z -476..-472) leads to the hall. */
    public static final BlockPos K3_MIN = new BlockPos(314, TEMPEL_VLOER - 1, -471), K3_MAX = new BlockPos(346, TEMPEL_VLOER + 11, -448);
    public static final List<BlockPos> K3_SPAWNS = List.of(w("ridderzaal.spawns.1"), w("ridderzaal.spawns.2"), w("ridderzaal.spawns.3"),
            w("ridderzaal.spawns.4"), w("ridderzaal.spawns.5"));
    public static final BlockPos K3_POORT_MIN = new BlockPos(327, TEMPEL_VLOER, -476), K3_POORT_MAX = new BlockPos(333, TEMPEL_VLOER + 4, -472);

    /** The boss hall of the Opperzwam (round, open floor radius 22). Its 4 Lichtzwammen are centre + {@link #OZ_LICHT_OFFSETS}. */
    public static final BlockPos OZ_CENTRUM = w("arena_opperzwam.centrum");
    public static final int OZ_STRAAL = 22;
    /** (stand outside the hall = in the Ridderzaal, in front of gate 4) */
    public static final BlockPos OZ_DEUR = w("arena_opperzwam.deur");
    public static final BlockPos OZ_BORD = w("arena_opperzwam.bord");
    public static final int OZ_RESPAWN = 5 * 60;
    public static final int[][] OZ_LICHT_OFFSETS = {{-13, 0, -13}, {13, 0, -13}, {-13, 0, 13}, {13, 0, 13}};
    /** The dome that breaks open in phase 3: radius around the centre, y from centre + ONDER (y 175) .. + BOVEN (y 194). */
    public static final int OZ_PLAFOND_STRAAL = 11, OZ_PLAFOND_ONDER = 23, OZ_PLAFOND_BOVEN = 42;

    // ---- De Mika-spion: the market stall in Zwamzoet and the caps he flees over -----------------------------------------
    public static final BlockPos MIKA_KRAAM = w("mika_spion_kraam");
    /** Caps (x, z, fallback top y): zuidw, west, oost (WereldPlekken hoed_*). The real top is read from the heightmap. */
    public static final int[][] MIKA_HOEDEN = {hoed("hoed_zuidw"), hoed("hoed_west"), hoed("hoed_oost")};
    public static final int MIKA_HOED_STRAAL = 9;
    public static final int MIKA_TERUG_SECONDEN = 10 * 60;

    private static int[] hoed(String id) {
        BlockPos b = w(id);
        return new int[] {b.getX(), b.getZ(), b.getY()};
    }
}
